SELECT DATE_TRUNC('MONTH', started_at) AS activity_month, (UNIX_TIMESTAMP(MAX(started_at)) - UNIX_TIMESTAMP(MIN(started_at))) / 60 AS duration_min, COUNT(CASE WHEN country = 'UK' THEN 1 END) AS uk_count, COUNT_IF(device = 'tablet') AS tablet_events, COUNT(*) AS cnt, COUNT(CASE WHEN country = 'JP' THEN 1 END) AS jp_count, SIZE(COLLECT_SET(device)) AS num_devices FROM sessions GROUP BY DATE_TRUNC('MONTH', started_at)
